   REDROOM FITNESS — Global Styles
   ============================================= */

/* --- CSS Variables --- */
:root {
  --bg-primary: #111111;
  --bg-secondary: #1a1a1a;
  --bg-card: #141414;
  --red-primary: #E63946;
  --red-hover: #c62833;
  --red-dark: #8b1a22;
  --white: #ffffff;
  --gray-100: #f5f5f5;
  --gray-200: #e0e0e0;
  --gray-300: #b0b0b0;
  --gray-400: #888888;
  --gray-500: #555555;
  --font-headline: 'Oswald', 'Bebas Neue', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1280px;
  --nav-height: 80px;
  --transition-fast: 0.2s ease;
  --transition-smooth: 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-headline);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  line-height: 1.1;
}
h1 { font-size: clamp(2.5rem, 8vw, 5rem); }
h2 { font-size: clamp(2rem, 5vw, 3.5rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
p { color: var(--gray-300); }

/* --- Layout --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 80px 0; }
.section--dark { background-color: var(--bg-secondary); }
.section--red { background-color: var(--red-primary); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px 32px;
  font-family: var(--font-headline);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border-radius: 4px;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.btn--primary {
  background-color: var(--red-primary);
  color: var(--white);
  border: 2px solid var(--red-primary);
}
.btn--primary:hover {
  background-color: var(--red-hover);
  border-color: var(--red-hover);
  transform: translateY(-2px);
}
.btn--outline {
  background-color: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn--outline:hover {
  background-color: var(--white);
  color: var(--bg-primary);
}
.btn--large {
  padding: 20px 48px;
  font-size: 1.125rem;
}
.btn--full { width: 100%; }

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background-color: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.nav__logo {
  font-family: var(--font-headline);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--red-primary);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}
.nav__logo span { color: var(--white); }
.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav__link {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-300);
  transition: color var(--transition-fast);
  position: relative;
}
.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--red-primary);
  transition: width var(--transition-fast);
}
.nav__link:hover { color: var(--white); }
.nav__link:hover::after { width: 100%; }
.nav__cta {
  display: flex;
  align-items: center;
  gap: 16px;
}
.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}
.nav__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--white);
  transition: all var(--transition-fast);
}

/* Mobile Nav */
@media (max-width: 1024px) {
  .nav__links { display: none; }
  .nav__cta .btn { display: none; }
  .nav__mobile-toggle { display: flex; }
  .nav--open .nav__mobile-toggle span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
  .nav--open .nav__mobile-toggle span:nth-child(2) { opacity: 0; }
  .nav--open .nav__mobile-toggle span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }
  .nav__mobile-menu {
    display: none;
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--bg-primary);
    padding: 40px 24px;
  }
  .nav--open .nav__mobile-menu { display: flex; flex-direction: column; gap: 24px; }
  .nav__mobile-menu .nav__link { font-size: 1.5rem; }
  .nav__mobile-menu .nav__cta { flex-direction: column; margin-top: 24px; }
}

/* --- Hero Sections --- */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: var(--nav-height);
  overflow: hidden;
}
.hero--full { min-height: 100vh; }
.hero--short { min-height: 60vh; }
.hero__bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0a0a0a 0%, #1a0a0a 50%, #0a0a0a 100%);
}
.hero__bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(230, 57, 70, 0.15) 0%, transparent 60%);
}
.hero__content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 900px;
  padding: 0 24px;
}
.hero__overline {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.3em;
  color: var(--red-primary);
  margin-bottom: 16px;
  text-transform: uppercase;
}
.hero__title { margin-bottom: 24px; }
.hero__subtitle {
  font-size: 1.125rem;
  color: var(--gray-300);
  max-width: 600px;
  margin: 0 auto 40px;
}
.hero__actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* --- Promo Bar --- */
.promo-bar {
  background-color: var(--red-primary);
  padding: 12px 24px;
  text-align: center;
}
.promo-bar__text {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--white);
}
.promo-bar__link {
  color: var(--white);
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 8px;
  transition: opacity var(--transition-fast);
}
.promo-bar__link:hover { opacity: 0.8; }

/* --- Section Headers --- */
.section-header {
  text-align: center;
  margin-bottom: 60px;
}
.section-header__title { margin-bottom: 16px; }
.section-header__subtitle {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto;
}

/* --- Community Promo --- */
.community-promo { background-color: var(--bg-secondary); }
.community-promo__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.community-promo__image {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #2a1a1a 0%, #1a1a1a 100%);
}
.community-promo__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(45deg, rgba(230, 57, 70, 0.2) 0%, transparent 50%);
}
.community-promo__image-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
