/* =============================================
   REDROOM FITNESS — Global Styles
   ============================================= */

/* --- CSS Variables --- */
:root {
  --bg-primary: #111111;
  --bg-secondary: #1a1a1a;
  --bg-card: #141414;
  --red-primary: #E63946;
  --red-hover: #c62833;
  --red-dark: #8b1a22;
  --white: #ffffff;
  --gray-100: #f5f5f5;
  --gray-200: #e0e0e0;
  --gray-300: #b0b0b0;
  --gray-400: #888888;
  --gray-500: #555555;
  --font-headline: 'Oswald', 'Bebas Neue', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1280px;
  --nav-height: 80px;
  --transition-fast: 0.2s ease;
  --transition-smooth: 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-headline);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  line-height: 1.1;
}
h1 { font-size: clamp(2.5rem, 8vw, 5rem); }
h2 { font-size: clamp(2rem, 5vw, 3.5rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
p { color: var(--gray-300); }

/* --- Layout --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 80px 0; }
.section--dark { background-color: var(--bg-secondary); }
.section--red { background-color: var(--red-primary); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px 32px;
  font-family: var(--font-headline);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border-radius: 4px;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.btn--primary {
  background-color: var(--red-primary);
  color: var(--white);
  border: 2px solid var(--red-primary);
}
.btn--primary:hover {
  background-color: var(--red-hover);
  border-color: var(--red-hover);
  transform: translateY(-2px);
}
.btn--outline {
  background-color: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn--outline:hover {
  background-color: var(--white);
  color: var(--bg-primary);
}
.btn--large {
  padding: 20px 48px;
  font-size: 1.125rem;
}
.btn--full { width: 100%; }

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background-color: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.nav__logo {
  font-family: var(--font-headline);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--red-primary);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}
.nav__logo span { color: var(--white); }
.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav__link {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-300);
  transition: color var(--transition-fast);
  position: relative;
}
.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--red-primary);
  transition: width var(--transition-fast);
}
.nav__link:hover { color: var(--white); }
.nav__link:hover::after { width: 100%; }
.nav__cta {
  display: flex;
  align-items: center;
  gap: 16px;
}
.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}
.nav__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--white);
  transition: all var(--transition-fast);
}

/* Mobile Nav */
@media (max-width: 1024px) {
  .nav__links { display: none; }
  .nav__cta .btn { display: none; }
  .nav__mobile-toggle { display: flex; }
  .nav--open .nav__mobile-toggle span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
  .nav--open .nav__mobile-toggle span:nth-child(2) { opacity: 0; }
  .nav--open .nav__mobile-toggle span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }
  .nav__mobile-menu {
    display: none;
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--bg-primary);
    padding: 40px 24px;
  }
  .nav--open .nav__mobile-menu { display: flex; flex-direction: column; gap: 24px; }
  .nav__mobile-menu .nav__link { font-size: 1.5rem; }
  .nav__mobile-menu .nav__cta { flex-direction: column; margin-top: 24px; }
}

/* --- Hero Sections --- */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: var(--nav-height);
  overflow: hidden;
}
.hero--full { min-height: 100vh; }
.hero--short { min-height: 60vh; }
.hero__bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0a0a0a 0%, #1a0a0a 50%, #0a0a0a 100%);
}
.hero__bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(230, 57, 70, 0.15) 0%, transparent 60%);
}
.hero__content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 900px;
  padding: 0 24px;
}
.hero__overline {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.3em;
  color: var(--red-primary);
  margin-bottom: 16px;
  text-transform: uppercase;
}
.hero__title { margin-bottom: 24px; }
.hero__subtitle {
  font-size: 1.125rem;
  color: var(--gray-300);
  max-width: 600px;
  margin: 0 auto 40px;
}
.hero__actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* --- Promo Bar --- */
.promo-bar {
  background-color: var(--red-primary);
  padding: 12px 24px;
  text-align: center;
}
.promo-bar__text {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--white);
}
.promo-bar__link {
  color: var(--white);
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 8px;
  transition: opacity var(--transition-fast);
}
.promo-bar__link:hover { opacity: 0.8; }

/* --- Section Headers --- */
.section-header {
  text-align: center;
  margin-bottom: 60px;
}
.section-header__title { margin-bottom: 16px; }
.section-header__subtitle {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto;
}

/* --- Community Promo --- */
.community-promo { background-color: var(--bg-secondary); }
.community-promo__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.community-promo__image {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #2a1a1a 0%, #1a1a1a 100%);
}
.community-promo__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(45deg, rgba(230, 57, 70, 0.2) 0%, transparent 50%);
}
.community-promo__image-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 3rem;
  color: var(--red-primary);
  opacity: 0.3;
}
.community-promo__content h2 { margin-bottom: 24px; }
.community-promo__content p { margin-bottom: 32px; font-size: 1.0625rem; }

/* --- Two Ways Section --- */
.two-ways__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  margin-top: 60px;
}
.two-ways__card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 48px 40px;
  text-align: center;
  transition: all var(--transition-smooth);
}
.two-ways__card:hover {
  border-color: var(--red-primary);
  transform: translateY(-8px);
  box-shadow: 0 20px 60px rgba(230, 57, 70, 0.15);
}
.two-ways__icon {
  width: 80px;
  height: 80px;
  margin: 0 auto 24px;
  background-color: rgba(230, 57, 70, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
}
.two-ways__card h3 { margin-bottom: 16px; }
.two-ways__card p { font-size: 1rem; }

/* --- Studio Experience --- */
.studio-exp {
  background: linear-gradient(rgba(17, 17, 17, 0.9), rgba(17, 17, 17, 0.9)),
              linear-gradient(135deg, #1a0505 0%, #0a0a0a 50%, #1a0505 100%);
  background-size: cover, cover;
  text-align: center;
}
.studio-exp h2 { margin-bottom: 24px; }
.studio-exp p { max-width: 600px; margin: 0 auto 40px; }

/* --- Free Trial CTA --- */
.free-trial-cta {
  background-color: var(--red-primary);
  text-align: center;
  padding: 100px 24px;
}
.free-trial-cta h2 { margin-bottom: 16px; }
.free-trial-cta p { color: rgba(255, 255, 255, 0.85); margin-bottom: 32px; }
.free-trial-cta .btn {
  background-color: var(--white);
  color: var(--red-primary);
  border-color: var(--white);
}
.free-trial-cta .btn:hover {
  background-color: var(--gray-100);
  border-color: var(--gray-100);
}

/* --- Carousel --- */
.carousel { position: relative; overflow: hidden; }
.carousel__track {
  display: flex;
  transition: transform var(--transition-smooth);
}
.carousel__slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #1a0a0a 0%, #0a0a0a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel__slide-content {
  text-align: center;
  padding: 40px;
}
.carousel__slide-content h3 {
  font-size: 2rem;
  margin-bottom: 16px;
}
.carousel__slide-placeholder {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0505 0%, #0f0f0f 50%, #1a0505 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel__slide-placeholder::before {
  content: '';
  position: absolute;
  width: 200px;
  height: 200px;
  border: 3px solid var(--red-primary);
  border-radius: 50%;
  opacity: 0.2;
}
.carousel__controls {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 12px;
}
.carousel__dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: var(--gray-500);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.carousel__dot--active {
  background-color: var(--red-primary);
  transform: scale(1.2);
}
.carousel__arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background-color: rgba(17, 17, 17, 0.8);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.25rem;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: 1px solid rgba(255, 255, 255, 0.1);
}
.carousel__arrow:hover {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
}
.carousel__arrow--prev { left: 24px; }
.carousel__arrow--next { right: 24px; }

/* --- Newsletter --- */
.newsletter {
  background-color: var(--bg-secondary);
  text-align: center;
}
.newsletter h2 { margin-bottom: 16px; }
.newsletter p { margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }
.newsletter__form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter__input {
  flex: 1;
  padding: 16px 20px;
  font-size: 1rem;
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  border-radius: 4px;
  color: var(--white);
  transition: border-color var(--transition-fast);
}
.newsletter__input:focus {
  outline: none;
  border-color: var(--red-primary);
}
.newsletter__input.error { border-color: #ff4444; }
.newsletter__error {
  color: #ff4444;
  font-size: 0.875rem;
  margin-top: 8px;
  display: none;
}
.newsletter__error.show { display: block; }
.newsletter__success {
  color: #44ff88;
  font-size: 0.875rem;
  margin-top: 8px;
  display: none;
}
.newsletter__success.show { display: block; }

/* --- Footer --- */
.footer {
  background-color: #0a0a0a;
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.footer__grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 60px;
  margin-bottom: 60px;
}
.footer__brand p {
  margin-top: 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  max-width: 280px;
}
.footer__column h4 {
  font-size: 0.875rem;
  margin-bottom: 20px;
  color: var(--white);
}
.footer__column ul { display: flex; flex-direction: column; gap: 12px; }
.footer__column a {
  font-size: 0.875rem;
  color: var(--gray-400);
  transition: color var(--transition-fast);
}
.footer__column a:hover { color: var(--red-primary); }
.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.footer__copyright {
  font-size: 0.75rem;
  color: var(--gray-500);
}
.footer__socials {
  display: flex;
  gap: 16px;
}
.footer__social {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.05);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  transition: all var(--transition-fast);
}
.footer__social:hover {
  background-color: var(--red-primary);
  color: var(--white);
}

/* --- Workout Page Specific --- */
.method-overview__content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.method-overview__text h2 { margin-bottom: 24px; }
.method-overview__text p { font-size: 1.0625rem; line-height: 1.8; }
.method-overview__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #2a1010 0%, #1a1a1a 100%);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}
.method-overview__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(230, 57, 70, 0.3) 0%, transparent 60%);
}
.method-overview__image-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 4rem;
  color: var(--red-primary);
  opacity: 0.2;
}

/* Floor/Treadmill Toggle */
.toggle-section {
  background-color: var(--bg-secondary);
}
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 48px;
}
.toggle-btn {
  padding: 16px 48px;
  font-family: var(--font-headline);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  transition: all var(--transition-fast);
}
.toggle-btn:first-child {
  border-radius: 4px 0 0 4px;
}
.toggle-btn:last-child {
  border-radius: 0 4px 4px 0;
  border-left: none;
}
.toggle-btn.active {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--white);
}
.toggle-btn:hover:not(.active) {
  background-color: rgba(230, 57, 70, 0.1);
  border-color: var(--red-primary);
  color: var(--white);
}
.toggle-content {
  display: none;
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.toggle-content.active { display: block; }
.toggle-content h3 { margin-bottom: 24px; }
.toggle-content p { font-size: 1.125rem; line-height: 1.8; }

/* Weekly Schedule Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--bg-card);
  border-radius: 12px;
  overflow: hidden;
}
.schedule-table th,
.schedule-table td {
  padding: 20px 24px;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.schedule-table th {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gray-400);
  background-color: rgba(0, 0, 0, 0.3);
}
.schedule-table td {
  font-size: 1rem;
}
.schedule-table tr:last-child td { border-bottom: none; }
.schedule-table tr:hover td { background-color: rgba(230, 57, 70, 0.05); }
.schedule-table .muscle-group {
  color: var(--red-primary);
  font-weight: 600;
}

/* --- Instructor Page Specific --- */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 12px 24px;
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--gray-400);
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  border-radius: 4px;
  transition: all var(--transition-fast);
}
.filter-btn.active,
.filter-btn:hover {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--white);
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 32px;
}
.instructor-card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  overflow: hidden;
  transition: all var(--transition-smooth);
}
.instructor-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-4px);
  box-shadow: 0 16px 48px rgba(230, 57, 70, 0.1);
}
.instructor-card__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #2a1010 0%, #1a1a1a 100%);
  position: relative;
  overflow: hidden;
}
.instructor-card__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(17, 17, 17, 0.8) 100%);
}
.instructor-card__placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 3rem;
  color: var(--red-primary);
  opacity: 0.3;
}
.instructor-card__info { padding: 24px; }
.instructor-card__name {
  font-family: var(--font-headline);
  font-size: 1.25rem;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.instructor-card__location {
  font-size: 0.875rem;
  color: var(--gray-400);
  margin-bottom: 16px;
}
.instructor-card__cta {
  display: inline-block;
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--red-primary);
  transition: color var(--transition-fast);
}
.instructor-card__cta:hover { color: var(--white); }
.instructor-card__cta::after {
  content: ' →';
  transition: transform var(--transition-fast);
}
.instructor-card__cta:hover::after { transform: translateX(4px); }

/* --- FAQ Accordion --- */
.faq-accordion { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.faq-item:first-child { border-top: 1px solid rgba(255, 255, 255, 0.1); }
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-family: var(--font-headline);
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--white);
  text-align: left;
  transition: color var(--transition-fast);
}
.faq-question:hover { color: var(--red-primary); }
.faq-icon {
  font-size: 1.5rem;
  font-weight: 300;
  transition: transform var(--transition-fast);
  color: var(--red-primary);
}
.faq-item.active .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-smooth), padding var(--transition-smooth);
}
.faq-item.active .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}
.faq-answer p {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--gray-300);
}

/* --- Digital Platform --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.feature-card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 40px 32px;
  text-align: center;
  transition: all var(--transition-smooth);
}
.feature-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-4px);
}
.feature-card__icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 24px;
  background-color: rgba(230, 57, 70, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.feature-card h3 { margin-bottom: 16px; font-size: 1.125rem; }
.feature-card p { font-size: 0.9375rem; }
.workout-types {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.workout-type {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: 32px 24px;
  text-align: center;
  transition: all var(--transition-fast);
}
.workout-type:hover { border-color: var(--red-primary); }
.workout-type h4 { font-size: 1rem; margin-bottom: 8px; }
.workout-type p { font-size: 0.8125rem; color: var(--gray-400); }

/* --- CTA Section --- */
.cta-section {
  text-align: center;
  padding: 100px 24px;
}
.cta-section h2 { margin-bottom: 16px; }
.cta-section p { max-width: 500px; margin: 0 auto 32px; }

/* --- Country Selector --- */
.country-selector {
  position: relative;
  display: inline-block;
}
.country-selector__btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  background-color: transparent;
  border: 1px solid var(--gray-500);
  border-radius: 4px;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.country-selector__btn:hover {
  border-color: var(--red-primary);
  color: var(--white);
}
.country-selector__dropdown {
  position: absolute;
  bottom: 100%;
  right: 0;
  margin-bottom: 8px;
  background-color: var(--bg-card);
  border: 1px solid var(--gray-500);
  border-radius: 4px;
  min-width: 150px;
  display: none;
  z-index: 100;
}
.country-selector.open .country-selector__dropdown { display: block; }
.country-selector__option {
  display: block;
  padding: 12px 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.country-selector__option:hover {
  background-color: var(--red-primary);
  color: var(--white);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .community-promo__inner { grid-template-columns: 1fr; gap: 40px; }
  .two-ways__grid { grid-template-columns: 1fr; }
  .method-overview__content { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .workout-types { grid-template-columns: repeat(2, 1fr); }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .section { padding: 60px 0; }
  .hero { min-height: 80vh; }
  .features-grid { grid-template-columns: 1fr; }
  .schedule-table th, .schedule-table td { padding: 12px 16px; font-size: 0.875rem; }
  .footer__grid { grid-template-columns: 1fr; gap: 40px; }
  .footer__bottom { flex-direction: column; gap: 24px; text-align: center; }
  .newsletter__form { flex-direction: column; }
}

/* =============================================
   REDROOM FITNESS — Global Styles
   ============================================= */

/* --- CSS Variables --- */
:root {
  --bg-primary: #111111;
  --bg-secondary: #1a1a1a;
  --bg-card: #141414;
  --red-primary: #E63946;
  --red-hover: #c62833;
  --red-dark: #8b1a22;
  --white: #ffffff;
  --gray-100: #f5f5f5;
  --gray-200: #e0e0e0;
  --gray-300: #b0b0b0;
  --gray-400: #888888;
  --gray-500: #555555;
  --font-headline: 'Oswald', 'Bebas Neue', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1280px;
  --nav-height: 80px;
  --transition-fast: 0.2s ease;
  --transition-smooth: 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-headline);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  line-height: 1.1;
}
h1 { font-size: clamp(2.5rem, 8vw, 5rem); }
h2 { font-size: clamp(2rem, 5vw, 3.5rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
p { color: var(--gray-300); }

/* --- Layout --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 80px 0; }
.section--dark { background-color: var(--bg-secondary); }
.section--red { background-color: var(--red-primary); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px 32px;
  font-family: var(--font-headline);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border-radius: 4px;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.btn--primary {
  background-color: var(--red-primary);
  color: var(--white);
  border: 2px solid var(--red-primary);
}
.btn--primary:hover {
  background-color: var(--red-hover);
  border-color: var(--red-hover);
  transform: translateY(-2px);
}
.btn--outline {
  background-color: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn--outline:hover {
  background-color: var(--white);
  color: var(--bg-primary);
}
.btn--large {
  padding: 20px 48px;
  font-size: 1.125rem;
}
.btn--full { width: 100%; }

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background-color: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.nav__logo {
  font-family: var(--font-headline);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--red-primary);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}
.nav__logo span { color: var(--white); }
.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav__link {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-300);
  transition: color var(--transition-fast);
  position: relative;
}
.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--red-primary);
  transition: width var(--transition-fast);
}
.nav__link:hover { color: var(--white); }
.nav__link:hover::after { width: 100%; }
.nav__cta {
  display: flex;
  align-items: center;
  gap: 16px;
}
.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}
.nav__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--white);
  transition: all var(--transition-fast);
}

/* Mobile Nav */
@media (max-width: 1024px) {
  .nav__links { display: none; }
  .nav__cta .btn { display: none; }
  .nav__mobile-toggle { display: flex; }
  .nav--open .nav__mobile-toggle span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
  .nav--open .nav__mobile-toggle span:nth-child(2) { opacity: 0; }
  .nav--open .nav__mobile-toggle span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }
  .nav__mobile-menu {
    display: none;
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--bg-primary);
    padding: 40px 24px;
  }
  .nav--open .nav__mobile-menu { display: flex; flex-direction: column; gap: 24px; }
  .nav__mobile-menu .nav__link { font-size: 1.5rem; }
  .nav__mobile-menu .nav__cta { flex-direction: column; margin-top: 24px; }
}

/* --- Hero Sections --- */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: var(--nav-height);
  overflow: hidden;
}
.hero--full { min-height: 100vh; }
.hero--short { min-height: 60vh; }
.hero__bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0a0a0a 0%, #1a0a0a 50%, #0a0a0a 100%);
}
.hero__bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(230, 57, 70, 0.15) 0%, transparent 60%);
}
.hero__content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 900px;
  padding: 0 24px;
}
.hero__overline {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.3em;
  color: var(--red-primary);
  margin-bottom: 16px;
  text-transform: uppercase;
}
.hero__title { margin-bottom: 24px; }
.hero__subtitle {
  font-size: 1.125rem;
  color: var(--gray-300);
  max-width: 600px;
  margin: 0 auto 40px;
}
.hero__actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* --- Promo Bar --- */
.promo-bar {
  background-color: var(--red-primary);
  padding: 12px 24px;
  text-align: center;
}
.promo-bar__text {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--white);
}
.promo-bar__link {
  color: var(--white);
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 8px;
  transition: opacity var(--transition-fast);
}
.promo-bar__link:hover { opacity: 0.8; }

/* --- Section Headers --- */
.section-header {
  text-align: center;
  margin-bottom: 60px;
}
.section-header__title { margin-bottom: 16px; }
.section-header__subtitle {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto;
}

/* --- Community Promo --- */
.community-promo { background-color: var(--bg-secondary); }
.community-promo__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.community-promo__image {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #2a1a1a 0%, #1a1a1a 100%);
}
.community-promo__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(45deg, rgba(230, 57, 70, 0.2) 0%, transparent 50%);
}
.community-promo__image-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 3rem;
  color: var(--red-primary);
  opacity: 0.3;
}
.community-promo__content h2 { margin-bottom: 24px; }
.community-promo__content p { margin-bottom: 32px; font-size: 1.0625rem; }

/* --- Two Ways Section --- */
.two-ways__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  margin-top: 60px;
}
.two-ways__card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 48px 40px;
  text-align: center;
  transition: all var(--transition-smooth);
}
.two-ways__card:hover {
  border-color: var(--red-primary);
  transform: translateY(-8px);
  box-shadow: 0 20px 60px rgba(230, 57, 70, 0.15);
}
.two-ways__icon {
  width: 80px;
  height: 80px;
  margin: 0 auto 24px;
  background-color: rgba(230, 57, 70, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
}
.two-ways__card h3 { margin-bottom: 16px; }
.two-ways__card p { font-size: 1rem; }

/* --- Studio Experience --- */
.studio-exp {
  background: linear-gradient(rgba(17, 17, 17, 0.9), rgba(17, 17, 17, 0.9)),
              linear-gradient(135deg, #1a0505 0%, #0a0a0a 50%, #1a0505 100%);
  background-size: cover, cover;
  text-align: center;
}
.studio-exp h2 { margin-bottom: 24px; }
.studio-exp p { max-width: 600px; margin: 0 auto 40px; }

/* --- Free Trial CTA --- */
.free-trial-cta {
  background-color: var(--red-primary);
  text-align: center;
  padding: 100px 24px;
}
.free-trial-cta h2 { margin-bottom: 16px; }
.free-trial-cta p { color: rgba(255, 255, 255, 0.85); margin-bottom: 32px; }
.free-trial-cta .btn {
  background-color: var(--white);
  color: var(--red-primary);
  border-color: var(--white);
}
.free-trial-cta .btn:hover {
  background-color: var(--gray-100);
  border-color: var(--gray-100);
}

/* --- Carousel --- */
.carousel { position: relative; overflow: hidden; }
.carousel__track {
  display: flex;
  transition: transform var(--transition-smooth);
}
.carousel__slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #1a0a0a 0%, #0a0a0a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel__slide-content {
  text-align: center;
  padding: 40px;
}
.carousel__slide-content h3 {
  font-size: 2rem;
  margin-bottom: 16px;
}
.carousel__slide-placeholder {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0505 0%, #0f0f0f 50%, #1a0505 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel__slide-placeholder::before {
  content: '';
  position: absolute;
  width: 200px;
  height: 200px;
  border: 3px solid var(--red-primary);
  border-radius: 50%;
  opacity: 0.2;
}
.carousel__controls {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 12px;
}
.carousel__dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: var(--gray-500);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.carousel__dot--active {
  background-color: var(--red-primary);
  transform: scale(1.2);
}
.carousel__arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background-color: rgba(17, 17, 17, 0.8);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.25rem;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: 1px solid rgba(255, 255, 255, 0.1);
}
.carousel__arrow:hover {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
}
.carousel__arrow--prev { left: 24px; }
.carousel__arrow--next { right: 24px; }

/* --- Newsletter --- */
.newsletter {
  background-color: var(--bg-secondary);
  text-align: center;
}
.newsletter h2 { margin-bottom: 16px; }
.newsletter p { margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }
.newsletter__form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter__input {
  flex: 1;
  padding: 16px 20px;
  font-size: 1rem;
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  border-radius: 4px;
  color: var(--white);
  transition: border-color var(--transition-fast);
}
.newsletter__input:focus {
  outline: none;
  border-color: var(--red-primary);
}
.newsletter__input.error { border-color: #ff4444; }
.newsletter__error {
  color: #ff4444;
  font-size: 0.875rem;
  margin-top: 8px;
  display: none;
}
.newsletter__error.show { display: block; }
.newsletter__success {
  color: #44ff88;
  font-size: 0.875rem;
  margin-top: 8px;
  display: none;
}
.newsletter__success.show { display: block; }

/* --- Footer --- */
.footer {
  background-color: #0a0a0a;
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.footer__grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 60px;
  margin-bottom: 60px;
}
.footer__brand p {
  margin-top: 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  max-width: 280px;
}
.footer__column h4 {
  font-size: 0.875rem;
  margin-bottom: 20px;
  color: var(--white);
}
.footer__column ul { display: flex; flex-direction: column; gap: 12px; }
.footer__column a {
  font-size: 0.875rem;
  color: var(--gray-400);
  transition: color var(--transition-fast);
}
.footer__column a:hover { color: var(--red-primary); }
.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.footer__copyright {
  font-size: 0.75rem;
  color: var(--gray-500);
}
.footer__socials {
  display: flex;
  gap: 16px;
}
.footer__social {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.05);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  transition: all var(--transition-fast);
}
.footer__social:hover {
  background-color: var(--red-primary);
  color: var(--white);
}

/* --- Workout Page Specific --- */
.method-overview__content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.method-overview__text h2 { margin-bottom: 24px; }
.method-overview__text p { font-size: 1.0625rem; line-height: 1.8; }
.method-overview__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #2a1010 0%, #1a1a1a 100%);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}
.method-overview__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(230, 57, 70, 0.3) 0%, transparent 60%);
}
.method-overview__image-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 4rem;
  color: var(--red-primary);
  opacity: 0.2;
}

/* Floor/Treadmill Toggle */
.toggle-section {
  background-color: var(--bg-secondary);
}
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 48px;
}
.toggle-btn {
  padding: 16px 48px;
  font-family: var(--font-headline);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  transition: all var(--transition-fast);
}
.toggle-btn:first-child {
  border-radius: 4px 0 0 4px;
}
.toggle-btn:last-child {
  border-radius: 0 4px 4px 0;
  border-left: none;
}
.toggle-btn.active {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--white);
}
.toggle-btn:hover:not(.active) {
  background-color: rgba(230, 57, 70, 0.1);
  border-color: var(--red-primary);
  color: var(--white);
}
.toggle-content {
  display: none;
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.toggle-content.active { display: block; }
.toggle-content h3 { margin-bottom: 24px; }
.toggle-content p { font-size: 1.125rem; line-height: 1.8; }

/* Weekly Schedule Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--bg-card);
  border-radius: 12px;
  overflow: hidden;
}
.schedule-table th,
.schedule-table td {
  padding: 20px 24px;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.schedule-table th {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gray-400);
  background-color: rgba(0, 0, 0, 0.3);
}
.schedule-table td {
  font-size: 1rem;
}
.schedule-table tr:last-child td { border-bottom: none; }
.schedule-table tr:hover td { background-color: rgba(230, 57, 70, 0.05); }
.schedule-table .muscle-group {
  color: var(--red-primary);
  font-weight: 600;
}

/* --- Instructor Page Specific --- */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 12px 24px;
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--gray-400);
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  border-radius: 4px;
  transition: all var(--transition-fast);
}
.filter-btn.active,
.filter-btn:hover {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--white);
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 32px;
}
.instructor-card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  overflow: hidden;
  transition: all var(--transition-smooth);
}
.instructor-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-4px);
  box-shadow: 0 16px 48px rgba(230, 57, 70, 0.1);
}
.instructor-card__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #2a1010 0%, #1a1a1a 100%);
  position: relative;
  overflow: hidden;
}
.instructor-card__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(17, 17, 17, 0.8) 100%);
}
.instructor-card__placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 3rem;
  color: var(--red-primary);
  opacity: 0.3;
}
.instructor-card__info { padding: 24px; }
.instructor-card__name {
  font-family: var(--font-headline);
  font-size: 1.25rem;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.instructor-card__location {
  font-size: 0.875rem;
  color: var(--gray-400);
  margin-bottom: 16px;
}
.instructor-card__cta {
  display: inline-block;
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--red-primary);
  transition: color var(--transition-fast);
}
.instructor-card__cta:hover { color: var(--white); }
.instructor-card__cta::after {
  content: ' →';
  transition: transform var(--transition-fast);
}
.instructor-card__cta:hover::after { transform: translateX(4px); }

/* --- FAQ Accordion --- */
.faq-accordion { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.faq-item:first-child { border-top: 1px solid rgba(255, 255, 255, 0.1); }
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-family: var(--font-headline);
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--white);
  text-align: left;
  transition: color var(--transition-fast);
}
.faq-question:hover { color: var(--red-primary); }
.faq-icon {
  font-size: 1.5rem;
  font-weight: 300;
  transition: transform var(--transition-fast);
  color: var(--red-primary);
}
.faq-item.active .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-smooth), padding var(--transition-smooth);
}
.faq-item.active .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}
.faq-answer p {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--gray-300);
}

/* --- Digital Platform --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.feature-card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 40px 32px;
  text-align: center;
  transition: all var(--transition-smooth);
}
.feature-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-4px);
}
.feature-card__icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 24px;
  background-color: rgba(230, 57, 70, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.feature-card h3 { margin-bottom: 16px; font-size: 1.125rem; }
.feature-card p { font-size: 0.9375rem; }
.workout-types {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.workout-type {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: 32px 24px;
  text-align: center;
  transition: all var(--transition-fast);
}
.workout-type:hover { border-color: var(--red-primary); }
.workout-type h4 { font-size: 1rem; margin-bottom: 8px; }
.workout-type p { font-size: 0.8125rem; color: var(--gray-400); }

/* --- CTA Section --- */
.cta-section {
  text-align: center;
  padding: 100px 24px;
}
.cta-section h2 { margin-bottom: 16px; }
.cta-section p { max-width: 500px; margin: 0 auto 32px; }

/* --- Country Selector --- */
.country-selector {
  position: relative;
  display: inline-block;
}
.country-selector__btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  background-color: transparent;
  border: 1px solid var(--gray-500);
  border-radius: 4px;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.country-selector__btn:hover {
  border-color: var(--red-primary);
  color: var(--white);
}
.country-selector__dropdown {
  position: absolute;
  bottom: 100%;
  right: 0;
  margin-bottom: 8px;
  background-color: var(--bg-card);
  border: 1px solid var(--gray-500);
  border-radius: 4px;
  min-width: 150px;
  display: none;
  z-index: 100;
}
.country-selector.open .country-selector__dropdown { display: block; }
.country-selector__option {
  display: block;
  padding: 12px 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.country-selector__option:hover {
  background-color: var(--red-primary);
  color: var(--white);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .community-promo__inner { grid-template-columns: 1fr; gap: 40px; }
  .two-ways__grid { grid-template-columns: 1fr; }
  .method-overview__content { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .workout-types { grid-template-columns: repeat(2, 1fr); }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .section { padding: 60px 0; }
  .hero { min-height: 80vh; }
  .features-grid { grid-template-columns: 1fr; }
  .schedule-table th, .schedule-table td { padding: 12px 16px; font-size: 0.875rem; }
  .footer__grid { grid-template-columns: 1fr; gap: 40px; }
  .footer__bottom { flex-direction: column; gap: 24px; text-align: center; }
  .newsletter__form { flex-direction: column; }
}

raw_arguments.content:
/* =============================================
   REDROOM FITNESS — Global Styles
   ============================================= */

/* --- CSS Variables --- */
:root {
  --bg-primary: #111111;
  --bg-secondary: #1a1a1a;
  --bg-card: #141414;
  --red-primary: #E63946;
  --red-hover: #c62833;
  --red-dark: #8b1a22;
  --white: #ffffff;
  --gray-100: #f5f5f5;
  --gray-200: #e0e0e0;
  --gray-300: #b0b0b0;
  --gray-400: #888888;
  --gray-500: #555555;
  --font-headline: 'Oswald', 'Bebas Neue', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1280px;
  --nav-height: 80px;
  --transition-fast: 0.2s ease;
  --transition-smooth: 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-headline);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  line-height: 1.1;
}
h1 { font-size: clamp(2.5rem, 8vw, 5rem); }
h2 { font-size: clamp(2rem, 5vw, 3.5rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
p { color: var(--gray-300); }

/* --- Layout --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 80px 0; }
.section--dark { background-color: var(--bg-secondary); }
.section--red { background-color: var(--red-primary); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px 32px;
  font-family: var(--font-headline);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border-radius: 4px;
  transition: all var(--transition-fast);
  cursor: pointer;
}
.btn--primary {
  background-color: var(--red-primary);
  color: var(--white);
  border: 2px solid var(--red-primary);
}
.btn--primary:hover {
  background-color: var(--red-hover);
  border-color: var(--red-hover);
  transform: translateY(-2px);
}
.btn--outline {
  background-color: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn--outline:hover {
  background-color: var(--white);
  color: var(--bg-primary);
}
.btn--large {
  padding: 20px 48px;
  font-size: 1.125rem;
}
.btn--full { width: 100%; }

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background-color: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.nav__logo {
  font-family: var(--font-headline);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--red-primary);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}
.nav__logo span { color: var(--white); }
.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav__link {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-300);
  transition: color var(--transition-fast);
  position: relative;
}
.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--red-primary);
  transition: width var(--transition-fast);
}
.nav__link:hover { color: var(--white); }
.nav__link:hover::after { width: 100%; }
.nav__cta {
  display: flex;
  align-items: center;
  gap: 16px;
}
.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}
.nav__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--white);
  transition: all var(--transition-fast);
}

/* Mobile Nav */
@media (max-width: 1024px) {
  .nav__links { display: none; }
  .nav__cta .btn { display: none; }
  .nav__mobile-toggle { display: flex; }
  .nav--open .nav__mobile-toggle span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
  .nav--open .nav__mobile-toggle span:nth-child(2) { opacity: 0; }
  .nav--open .nav__mobile-toggle span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }
  .nav__mobile-menu {
    display: none;
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--bg-primary);
    padding: 40px 24px;
  }
  .nav--open .nav__mobile-menu { display: flex; flex-direction: column; gap: 24px; }
  .nav__mobile-menu .nav__link { font-size: 1.5rem; }
  .nav__mobile-menu .nav__cta { flex-direction: column; margin-top: 24px; }
}

/* --- Hero Sections --- */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: var(--nav-height);
  overflow: hidden;
}
.hero--full { min-height: 100vh; }
.hero--short { min-height: 60vh; }
.hero__bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0a0a0a 0%, #1a0a0a 50%, #0a0a0a 100%);
}
.hero__bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(230, 57, 70, 0.15) 0%, transparent 60%);
}
.hero__content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 900px;
  padding: 0 24px;
}
.hero__overline {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.3em;
  color: var(--red-primary);
  margin-bottom: 16px;
  text-transform: uppercase;
}
.hero__title { margin-bottom: 24px; }
.hero__subtitle {
  font-size: 1.125rem;
  color: var(--gray-300);
  max-width: 600px;
  margin: 0 auto 40px;
}
.hero__actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* --- Promo Bar --- */
.promo-bar {
  background-color: var(--red-primary);
  padding: 12px 24px;
  text-align: center;
}
.promo-bar__text {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--white);
}
.promo-bar__link {
  color: var(--white);
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 8px;
  transition: opacity var(--transition-fast);
}
.promo-bar__link:hover { opacity: 0.8; }

/* --- Section Headers --- */
.section-header {
  text-align: center;
  margin-bottom: 60px;
}
.section-header__title { margin-bottom: 16px; }
.section-header__subtitle {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto;
}

/* --- Community Promo --- */
.community-promo { background-color: var(--bg-secondary); }
.community-promo__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.community-promo__image {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #2a1a1a 0%, #1a1a1a 100%);
}
.community-promo__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(45deg, rgba(230, 57, 70, 0.2) 0%, transparent 50%);
}
.community-promo__image-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 3rem;
  color: var(--red-primary);
  opacity: 0.3;
}
.community-promo__content h2 { margin-bottom: 24px; }
.community-promo__content p { margin-bottom: 32px; font-size: 1.0625rem; }

/* --- Two Ways Section --- */
.two-ways__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  margin-top: 60px;
}
.two-ways__card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 48px 40px;
  text-align: center;
  transition: all var(--transition-smooth);
}
.two-ways__card:hover {
  border-color: var(--red-primary);
  transform: translateY(-8px);
  box-shadow: 0 20px 60px rgba(230, 57, 70, 0.15);
}
.two-ways__icon {
  width: 80px;
  height: 80px;
  margin: 0 auto 24px;
  background-color: rgba(230, 57, 70, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
}
.two-ways__card h3 { margin-bottom: 16px; }
.two-ways__card p { font-size: 1rem; }

/* --- Studio Experience --- */
.studio-exp {
  background: linear-gradient(rgba(17, 17, 17, 0.9), rgba(17, 17, 17, 0.9)),
              linear-gradient(135deg, #1a0505 0%, #0a0a0a 50%, #1a0505 100%);
  background-size: cover, cover;
  text-align: center;
}
.studio-exp h2 { margin-bottom: 24px; }
.studio-exp p { max-width: 600px; margin: 0 auto 40px; }

/* --- Free Trial CTA --- */
.free-trial-cta {
  background-color: var(--red-primary);
  text-align: center;
  padding: 100px 24px;
}
.free-trial-cta h2 { margin-bottom: 16px; }
.free-trial-cta p { color: rgba(255, 255, 255, 0.85); margin-bottom: 32px; }
.free-trial-cta .btn {
  background-color: var(--white);
  color: var(--red-primary);
  border-color: var(--white);
}
.free-trial-cta .btn:hover {
  background-color: var(--gray-100);
  border-color: var(--gray-100);
}

/* --- Carousel --- */
.carousel { position: relative; overflow: hidden; }
.carousel__track {
  display: flex;
  transition: transform var(--transition-smooth);
}
.carousel__slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #1a0a0a 0%, #0a0a0a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel__slide-content {
  text-align: center;
  padding: 40px;
}
.carousel__slide-content h3 {
  font-size: 2rem;
  margin-bottom: 16px;
}
.carousel__slide-placeholder {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0505 0%, #0f0f0f 50%, #1a0505 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel__slide-placeholder::before {
  content: '';
  position: absolute;
  width: 200px;
  height: 200px;
  border: 3px solid var(--red-primary);
  border-radius: 50%;
  opacity: 0.2;
}
.carousel__controls {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 12px;
}
.carousel__dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: var(--gray-500);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.carousel__dot--active {
  background-color: var(--red-primary);
  transform: scale(1.2);
}
.carousel__arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background-color: rgba(17, 17, 17, 0.8);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.25rem;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: 1px solid rgba(255, 255, 255, 0.1);
}
.carousel__arrow:hover {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
}
.carousel__arrow--prev { left: 24px; }
.carousel__arrow--next { right: 24px; }

/* --- Newsletter --- */
.newsletter {
  background-color: var(--bg-secondary);
  text-align: center;
}
.newsletter h2 { margin-bottom: 16px; }
.newsletter p { margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }
.newsletter__form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter__input {
  flex: 1;
  padding: 16px 20px;
  font-size: 1rem;
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  border-radius: 4px;
  color: var(--white);
  transition: border-color var(--transition-fast);
}
.newsletter__input:focus {
  outline: none;
  border-color: var(--red-primary);
}
.newsletter__input.error { border-color: #ff4444; }
.newsletter__error {
  color: #ff4444;
  font-size: 0.875rem;
  margin-top: 8px;
  display: none;
}
.newsletter__error.show { display: block; }
.newsletter__success {
  color: #44ff88;
  font-size: 0.875rem;
  margin-top: 8px;
  display: none;
}
.newsletter__success.show { display: block; }

/* --- Footer --- */
.footer {
  background-color: #0a0a0a;
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.footer__grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 60px;
  margin-bottom: 60px;
}
.footer__brand p {
  margin-top: 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  max-width: 280px;
}
.footer__column h4 {
  font-size: 0.875rem;
  margin-bottom: 20px;
  color: var(--white);
}
.footer__column ul { display: flex; flex-direction: column; gap: 12px; }
.footer__column a {
  font-size: 0.875rem;
  color: var(--gray-400);
  transition: color var(--transition-fast);
}
.footer__column a:hover { color: var(--red-primary); }
.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.footer__copyright {
  font-size: 0.75rem;
  color: var(--gray-500);
}
.footer__socials {
  display: flex;
  gap: 16px;
}
.footer__social {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.05);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  transition: all var(--transition-fast);
}
.footer__social:hover {
  background-color: var(--red-primary);
  color: var(--white);
}

/* --- Workout Page Specific --- */
.method-overview__content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.method-overview__text h2 { margin-bottom: 24px; }
.method-overview__text p { font-size: 1.0625rem; line-height: 1.8; }
.method-overview__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #2a1010 0%, #1a1a1a 100%);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}
.method-overview__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(230, 57, 70, 0.3) 0%, transparent 60%);
}
.method-overview__image-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 4rem;
  color: var(--red-primary);
  opacity: 0.2;
}

/* Floor/Treadmill Toggle */
.toggle-section {
  background-color: var(--bg-secondary);
}
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 48px;
}
.toggle-btn {
  padding: 16px 48px;
  font-family: var(--font-headline);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  transition: all var(--transition-fast);
}
.toggle-btn:first-child {
  border-radius: 4px 0 0 4px;
}
.toggle-btn:last-child {
  border-radius: 0 4px 4px 0;
  border-left: none;
}
.toggle-btn.active {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--white);
}
.toggle-btn:hover:not(.active) {
  background-color: rgba(230, 57, 70, 0.1);
  border-color: var(--red-primary);
  color: var(--white);
}
.toggle-content {
  display: none;
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.toggle-content.active { display: block; }
.toggle-content h3 { margin-bottom: 24px; }
.toggle-content p { font-size: 1.125rem; line-height: 1.8; }

/* Weekly Schedule Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--bg-card);
  border-radius: 12px;
  overflow: hidden;
}
.schedule-table th,
.schedule-table td {
  padding: 20px 24px;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.schedule-table th {
  font-family: var(--font-headline);
  font-size: 0.875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gray-400);
  background-color: rgba(0, 0, 0, 0.3);
}
.schedule-table td {
  font-size: 1rem;
}
.schedule-table tr:last-child td { border-bottom: none; }
.schedule-table tr:hover td { background-color: rgba(230, 57, 70, 0.05); }
.schedule-table .muscle-group {
  color: var(--red-primary);
  font-weight: 600;
}

/* --- Instructor Page Specific --- */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 12px 24px;
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--gray-400);
  background-color: var(--bg-card);
  border: 2px solid var(--gray-500);
  border-radius: 4px;
  transition: all var(--transition-fast);
}
.filter-btn.active,
.filter-btn:hover {
  background-color: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--white);
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 32px;
}
.instructor-card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  overflow: hidden;
  transition: all var(--transition-smooth);
}
.instructor-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-4px);
  box-shadow: 0 16px 48px rgba(230, 57, 70, 0.1);
}
.instructor-card__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #2a1010 0%, #1a1a1a 100%);
  position: relative;
  overflow: hidden;
}
.instructor-card__image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(17, 17, 17, 0.8) 100%);
}
.instructor-card__placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 3rem;
  color: var(--red-primary);
  opacity: 0.3;
}
.instructor-card__info { padding: 24px; }
.instructor-card__name {
  font-family: var(--font-headline);
  font-size: 1.25rem;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.instructor-card__location {
  font-size: 0.875rem;
  color: var(--gray-400);
  margin-bottom: 16px;
}
.instructor-card__cta {
  display: inline-block;
  font-family: var(--font-headline);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--red-primary);
  transition: color var(--transition-fast);
}
.instructor-card__cta:hover { color: var(--white); }
.instructor-card__cta::after {
  content: ' →';
  transition: transform var(--transition-fast);
}
.instructor-card__cta:hover::after { transform: translateX(4px); }

/* --- FAQ Accordion --- */
.faq-accordion { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.faq-item:first-child { border-top: 1px solid rgba(255, 255, 255, 0.1); }
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-family: var(--font-headline);
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--white);
  text-align: left;
  transition: color var(--transition-fast);
}
.faq-question:hover { color: var(--red-primary); }
.faq-icon {
  font-size: 1.5rem;
  font-weight: 300;
  transition: transform var(--transition-fast);
  color: var(--red-primary);
}
.faq-item.active .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-smooth), padding var(--transition-smooth);
}
.faq-item.active .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}
.faq-answer p {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--gray-300);
}

/* --- Digital Platform --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.feature-card {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 40px 32px;
  text-align: center;
  transition: all var(--transition-smooth);
}
.feature-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-4px);
}
.feature-card__icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 24px;
  background-color: rgba(230, 57, 70, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.feature-card h3 { margin-bottom: 16px; font-size: 1.125rem; }
.feature-card p { font-size: 0.9375rem; }
.workout-types {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.workout-type {
  background-color: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: 32px 24px;
  text-align: center;
  transition: all var(--transition-fast);
}
.workout-type:hover { border-color: var(--red-primary); }
.workout-type h4 { font-size: 1rem; margin-bottom: 8px; }
.workout-type p { font-size: 0.8125rem; color: var(--gray-400); }

/* --- CTA Section --- */
.cta-section {
  text-align: center;
  padding: 100px 24px;
}
.cta-section h2 { margin-bottom: 16px; }
.cta-section p { max-width: 500px; margin: 0 auto 32px; }

/* --- Country Selector --- */
.country-selector {
  position: relative;
  display: inline-block;
}
.country-selector__btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  background-color: transparent;
  border: 1px solid var(--gray-500);
  border-radius: 4px;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.country-selector__btn:hover {
  border-color: var(--red-primary);
  color: var(--white);
}
.country-selector__dropdown {
  position: absolute;
  bottom: 100%;
  right: 0;
  margin-bottom: 8px;
  background-color: var(--bg-card);
  border: 1px solid var(--gray-500);
  border-radius: 4px;
  min-width: 150px;
  display: none;
  z-index: 100;
}
.country-selector.open .country-selector__dropdown { display: block; }
.country-selector__option {
  display: block;
  padding: 12px 16px;
  font-size: 0.875rem;
  color: var(--gray-400);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.country-selector__option:hover {
  background-color: var(--red-primary);
  color: var(--white);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .community-promo__inner { grid-template-columns: 1fr; gap: 40px; }
  .two-ways__grid { grid-template-columns: 1fr; }
